/bin/zsh -lc "python3 - <<'PY'
import json,re,hashlib
from pathlib import Path
base=Path('/Users/nahyeonbin/Desktop/_Codex/ducttape-poster-round6/blind-W1707EE5B')
packet=json.loads((base/'packet.json').read_text())
pre=json.loads((base/'reviews/craft-action-first.json').read_text())
main=json.loads((base/'reviews/craft.json').read_text())
md=(base/'reviews/craft.md').read_text()
assert set(main)=={'reviewer','order_compliant','method','viewed','images','sets'}
assert main['reviewer']=='craft' and main['order_compliant'] is True
assert main['method'].startswith('manual visual transcription')
assert set(main['images'])=={x['image_id'] for x in packet['images']}
assert set(main['sets'])==set(packet['cases'])==set(packet['sets'])
expected={(x['image_id'],v,x[v]) for x in packet['images'] for v in ['native','usage720','thumbnail320']}
actual={(v['image_id'],v['view'],v['path']) for v in main['viewed']}
assert len(main['viewed'])==15 and actual==expected
assert all(set(v)=={'image_id','view','path'} for v in main['viewed'])
dims={'content_form','hierarchy','typography','space','image_material','emotion_control','ai_slop'}
normalize=lambda s:re.sub(r'\\s+',' ',s).strip()
for source in packet['images']:
 image_id=source['image_id']
 value=main['images'][image_id]
 assert set(value)=={'mandatory','scores','evidence','residuals'}
 assert set(value['scores'])==dims==set(value['evidence'])
 assert all(type(n) is int and 1<=n<=5 for n in value['scores'].values())
 assert all(type(s) is str and s for s in value['evidence'].values())
 mandatory=value['mandatory']
 assert set(mandatory)=={'pass','issues','uncertainties','transcription','use_readings'}
 assert type(mandatory['pass']) is bool
 assert all(type(mandatory[k]) is list for k in ['issues','uncertainties','transcription'])
 assert set(mandatory['use_readings'])=={'all_required_copy_legible_at720','observations'}
 assert type(mandatory['use_readings']['all_required_copy_legible_at720']) is bool
 assert mandatory['use_readings']['all_required_copy_legible_at720'] is True
 copy=packet['cases'][source['case_id']]['copy']
 assert [t['required'] for t in mandatory['transcription']]==copy
 for t in mandatory['transcription']:
  assert set(t)=={'required','observed','equal'}
  assert type(t['equal']) is bool
  assert t['equal']==(normalize(t['required'])==normalize(t['observed']))
  assert json.dumps(t['required'],ensure_ascii=False) in md
  assert json.dumps(t['observed'],ensure_ascii=False) in md
 for text in mandatory['issues']+mandatory['uncertainties']+list(value['evidence'].values())+value['residuals']+[mandatory['use_readings']['observations']]:
  assert text in md
for case_id,value in main['sets'].items():
 assert set(value)=={'members','diversity','closest_pair','evidence','residuals'}
 assert value['members']==packet['sets'][case_id]['members']
 assert type(value['diversity']) is int and 1<=value['diversity']<=5
 pair=value['closest_pair']
 assert set(pair)=={'members','score','evidence'}
 assert len(pair['members'])==2 and len(set(pair['members']))==2
 assert set(pair['members'])<=set(value['members'])
 assert type(pair['score']) is int and 1<=pair['score']<=5
 for text in [value['evidence'],pair['evidence']]+value['residuals']:
  assert text in md
for v in main['viewed']:
 assert '| '+v['image_id']+' | '+v['view']+' | '+v['path']+' |' in md
assert set(pre)=={'reviewer','order_compliant','method','viewed','readings'}
assert pre['reviewer']=='craft' and pre['order_compliant'] is True
ids=['X4979','X7713','X5251','X4097','X3255']
assert [v['image_id'] for v in pre['viewed']]==ids
assert [v['image_id'] for v in pre['readings']]==ids
uncertainty='The date separator is visibly a horizontal dash, transcribed as an en dash (–); pixels alone do not establish its encoded Unicode character.'
for i,v,r in zip(ids,pre['viewed'],pre['readings']):
 path=str(base/'images'/f'{i}-usage720.png')
 assert v=={'image_id':i,'view':'usage720','path':path}
 assert r=={'image_id':i,'path':path,'fields':{'event_date_range_line':'2026.12.05–12.13','location_line':'가상 전시장 둥근방 / ROUND ROOM'},'uncertainties':[uncertainty]}
print('PASS: exact main and preflight schemas; unchanged initial fields; 15 exact view records; all 5 images, 30 full-copy transcriptions, 35 integer scores with evidence, mandatory fields and 720 observations; exact R6-C4 members and closest pair; complete Markdown coverage.')
for name in ['craft-action-first.json','craft.json','craft.md']:
 path=base/'reviews'/name
 print(f'{path}: {path.stat().st_size} bytes; SHA256 {hashlib.sha256(path.read_bytes()).hexdigest()}')
PY"

